await clickNav('#/about');
check('nav to about', h1() === 'О приложении', `(${h1()})`);
w.history.back();
await tick();
check('history back -> tasks', h1() === 'Задачи', `(${h1()})`);
w.location.hash = '#/nope';
await tick();
