setInput($('.task-input input'), 'Написать отчёт');
await tick();
addBtn().click();
await tick();
check('button adds second task', $$('.task-item').length === 2, `(${$$('.task-item').length})`);
check('input cleared after add', $('.task-input input').value === '');
check('counter shows 2 of 2', $('.page-card').textContent.includes('Не выполнено: 2 из 2'));
$$('.task-item input[type=checkbox]')[0].click();
await tick();
check('toggle marks done', $$('.task-item input[type=checkbox]')[0].checked === true);
check('counter shows 1 of 2', $('.page-card').textContent.includes('Не выполнено: 1 из 2'));
const saved = JSON.parse(w.localStorage.getItem('app-tasks'));
check('tasks saved to localStorage', saved.length === 2 && saved[0].done === true && saved[1].done === false,
  JSON.stringify(saved.map((t) => [t.text, t.done])));
$$('.task-item button').find((b) => b.textContent === 'Удалить').click();
await tick();
check('delete removes task', $$('.task-item').length === 1 && $('.task-item').textContent.includes('Написать отчёт'));

await toggleTheme();
const darkBg = appBg();
check('toggle changes background', darkBg !== startBg, `start=${startBg} now=${darkBg}`);
check('theme saved as dark', w.localStorage.getItem('app-theme') === 'dark');
check('switch checked in dark', $$('header input[type=checkbox]')[0].checked === true);
check('root has dark theme class', $('.app').parentElement.className.includes('g-root_theme_dark'), `parent=${$('.app').parentElement.className}`);
await toggleTheme();
check('toggle back to light', appBg() === startBg && w.localStorage.getItem('app-theme') === 'light');

const w2 = makeDom('http://localhost/#/tasks', {
  'app-theme': 'dark',
  'app-tasks': JSON.stringify([{ id: 'a', text: 'Saved task', done: true }]),
});
await tick();
const d2 = w2.document;
check('reload keeps dark theme', w2.localStorage.getItem('app-theme') === 'dark' && d2.querySelector('header input[type=checkbox]').checked === true);
check('reload restores tasks', d2.querySelectorAll('.task-item').length === 1 && d2.querySelector('.task-item input').checked === true);
