import { chromium } from 'playwright';

const URL = 'http://127.0.0.1:5173/';
const errors = [];
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1000, height: 800 }, colorScheme: 'light' });
const page = await ctx.newPage();
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

const bg = () => page.evaluate(() => getComputedStyle(document.querySelector('.app')).backgroundColor);
const h1 = () => page.evaluate(() => document.querySelector('main h1')?.textContent);
const checks = [];
const check = (name, ok, extra = '') => checks.push(`${ok ? 'PASS' : 'FAIL'} ${name} ${extra}`);

await page.goto(URL);
await page.waitForSelector('.app');
check('home page heading', (await h1()) === 'Добро пожаловать', `(${await h1()})`);
check('light bg on start', (await bg()) !== (await (async () => 'x')()), `bg=${await bg()}`);
const lightBg = await bg();

// navigate via nav
await page.click('nav a[href="#/tasks"]');
check('navigated to tasks via hash', page.url().endsWith('#/tasks'), page.url());
check('tasks heading', (await h1()) === 'Задачи', `(${await h1()})`);
await page.click('nav a[href="#/about"]');
check('about heading', (await h1()) === 'О приложении', `(${await h1()})`);
await page.goBack();
await page.waitForTimeout(100);
check('browser back works', (await h1()) === 'Задачи', `(${await h1()})`);
await page.goto(URL + '#/nope');
check('404 page', (await h1()) === 'Страница не найдена', `(${await h1()})`);
await page.goto(URL + '#/tasks');

// tasks: add, toggle, persist
await page.fill('.task-input input', 'Купить молоко');
await page.keyboard.press('Enter');
await page.fill('.task-input input', 'Написать отчёт');
await page.click('.task-add button:has-text("Добавить")');
const items = await page.locator('.task-item').count();
check('two tasks added', items === 2, `(${items})`);
await page.locator('.task-item input[type=checkbox]').first().check({ force: true });
const counter = await page.textContent('.task-list ~ *, .page-card > span >> nth=0').catch(() => '');
check('first task checked', await page.locator('.task-item input[type=checkbox]').first().isChecked());
await page.reload();
check('tasks persist after reload', (await page.locator('.task-item').count()) === 2);
check('done state persists after reload', await page.locator('.task-item input[type=checkbox]').first().isChecked());

// theme toggle
const sw = page.locator('header label', { hasText: 'Тёмная тема' });
await sw.click();
await page.waitForTimeout(200);
const darkBg = await bg();
check('dark theme applied', darkBg !== lightBg, `light=${lightBg} dark=${darkBg}`);
check('saved to localStorage', (await page.evaluate(() => localStorage.getItem('app-theme'))) === 'dark');
await page.screenshot({ path: '/tmp/shot-tasks-dark.png', fullPage: true });
await page.reload();
await page.waitForSelector('.app');
check('theme persists after reload', (await bg()) === darkBg, `bg=${await bg()}`);
await page.click('nav a[href="#/"]');
await page.screenshot({ path: '/tmp/shot-home-dark.png', fullPage: true });
await sw.click();
await page.waitForTimeout(200);
check('switch back to light', (await bg()) === lightBg, `bg=${await bg()}`);
await page.screenshot({ path: '/tmp/shot-home-light.png', fullPage: true });

// system preference default (no saved value)
const ctx2 = await browser.newContext({ colorScheme: 'dark' });
const p2 = await ctx2.newPage();
await p2.goto(URL);
await p2.waitForSelector('.app');
check('defaults to system dark when nothing saved', (await p2.evaluate(() => getComputedStyle(document.querySelector('.app')).backgroundColor)) === darkBg, '');

console.log(checks.join('\n'));
console.log('errors:', errors.length ? errors : 'none');
await browser.close();
